WITH cleaned AS (SELECT id, full_name, email, dept_id, job_title, salary, hire_date, is_remote, level, FLOOR(salary) AS salary_whole, CAST(is_remote AS INT) AS is_remote_flag, COALESCE(level, 'OTHER') AS resolved_level FROM employees WHERE hire_date > DATE '2023-04-29' AND level IS NOT NULL), with_windows AS (SELECT *, AVG(salary) OVER w_part AS salary_avg_2_prior, CUME_DIST() OVER w_running AS salary_whole_cume_dist FROM cleaned WINDOW w_part AS (PARTITION BY job_title ORDER BY is_remote_flag, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING), w_running AS (ORDER BY salary_whole DESC NULLS FIRST)), with_windows_employees AS (SELECT *, SUM(salary_whole) OVER (PARTITION BY dept_id ORDER BY salary_avg_2_prior, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_salary_whole, NTILE(5) OVER (PARTITION BY job_title ORDER BY salary_whole, id) AS salary_whole_bucket, AVG(salary) OVER (PARTITION BY dept_id ORDER BY hire_date, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS salary_avg_5 FROM with_windows), base AS (SELECT id, email, dept_id, hire_date, is_remote, level, salary_whole, is_remote_flag, salary_avg_2_prior, salary_whole_cume_dist, running_salary_whole, salary_whole_bucket, salary_avg_5, CASE WHEN is_remote THEN 'Yes' ELSE 'No' END AS is_remote_label, CASE WHEN salary_whole_bucket >= 7 THEN 'High' WHEN salary_whole_bucket >= 3 THEN 'Medium' ELSE 'Low' END AS salary_whole_bucket_level FROM with_windows_employees WHERE hire_date > TO_DATE('2023-09-06')), with_windows_employees_2 AS (SELECT *, SUM(salary_avg_5) OVER (PARTITION BY level ORDER BY salary_whole_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary_avg_5, AVG(salary_whole) OVER (PARTITION BY level ORDER BY hire_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS salary_whole_avg_2, ROW_NUMBER() OVER (ORDER BY running_salary_whole, id) AS event_seq, PERCENT_RANK() OVER (PARTITION BY dept_id ORDER BY salary_whole NULLS FIRST) AS salary_whole_percent_rank, FIRST_VALUE(salary_avg_5) IGNORE NULLS OVER (PARTITION BY dept_id ORDER BY salary_whole_cume_dist, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_salary_avg_5 FROM base), with_windows_employees_3 AS (SELECT *, AVG(running_salary_whole) OVER (PARTITION BY dept_id, level ORDER BY salary_whole_bucket, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS running_salary_whole_avg_6, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary_whole_percent_rank DESC, id) AS row_seq, ROUND(cumulative_salary_avg_5 / SUM(cumulative_salary_avg_5) OVER (PARTITION BY level), 4) AS cumulative_salary_avg_5_share, NTILE(5) OVER (PARTITION BY dept_id ORDER BY salary_whole_bucket, id) AS salary_whole_bucket_bucket FROM with_windows_employees_2), enriched AS (SELECT a.*, p.location FROM with_windows_employees_3 a INNER JOIN departments p ON a.dept_id = p.id) SELECT id, hire_date, level, salary_whole, is_remote_flag, salary_avg_2_prior, salary_whole_cume_dist, salary_whole_bucket, salary_avg_5 FROM enriched ORDER BY salary_whole DESC;
